using FluentValidation;

namespace FamilyVeda.Application.Triage;

public sealed class CreateEpisodeRequestValidator : AbstractValidator<CreateEpisodeRequest>
{
    public CreateEpisodeRequestValidator()
    {
        RuleFor(x => x.Symptoms).NotEmpty();
        RuleForEach(x => x.Symptoms).NotEmpty().MaximumLength(120);
        RuleFor(x => x.DurationDays).GreaterThanOrEqualTo(0).LessThanOrEqualTo(3650);
        RuleFor(x => x.Severity).InclusiveBetween(1, 10);
        RuleFor(x => x.Notes).MaximumLength(2000);
    }
}
